package com.rumitx.app.repeaters;
import android.app.AlertDialog;import android.os.*;import android.content.*;import android.location.Location;import android.widget.*;import java.io.*;import java.util.*;import java.util.concurrent.*;
public final class RepeaterActivity extends FeatureActivity {
 private RepeaterDatabase db;private ListView list;private TextView status;private List<Repeater> rows=new ArrayList<>();private final ExecutorService worker=Executors.newSingleThreadExecutor();private boolean nearest;private double radius=100;
 protected void onCreate(Bundle state){super.onCreate(state);db=new RepeaterDatabase(this);LinearLayout root=column();root.addView(label("REPEATER DATABASE / OFFLINE",22));root.addView(label("Import your own personal-use export. No repeater records are bundled.",13));LinearLayout bar=new LinearLayout(this);bar.addView(button("Import CSV",this::importOptions),new LinearLayout.LayoutParams(0,-2,1));bar.addView(button("Map",()->startActivity(new Intent(this,RepeaterMapActivity.class))),new LinearLayout.LayoutParams(0,-2,1));root.addView(bar);LinearLayout sorting=new LinearLayout(this);sorting.addView(button("All",()->{nearest=false;reload();}),new LinearLayout.LayoutParams(0,-2,1));sorting.addView(button("Nearest",()->{nearest=true;locationFeature();}),new LinearLayout.LayoutParams(0,-2,1));sorting.addView(button("Radius",this::radiusDialog),new LinearLayout.LayoutParams(0,-2,1));root.addView(sorting);locationState=label("Location not requested. All records are available without GPS.",12);root.addView(locationState);root.addView(button("Location",this::locationFeature));root.addView(button("DMR Identity",()->com.rumitx.app.IdentityDialog.show(this,()->new Thread(()->com.rumitx.app.RadioController.getInstance().applyIdentityToCurrentChannel(),"RumiTX-identity").start())));android.widget.Switch takShare=new android.widget.Switch(this);takShare.setText("Share repeaters to TAK");takShare.setMinHeight((int)(48*getResources().getDisplayMetrics().density));takShare.setChecked(com.rumitx.app.tak.TakSettings.enabled(this,"repeaters"));takShare.setOnCheckedChangeListener((button,on)->{com.rumitx.app.tak.TakSettings.set(this,"repeaters",on);com.rumitx.app.tak.TakSettings.refresh(this);});root.addView(takShare);status=label("Loading…",13);root.addView(status);list=new ListView(this);root.addView(list,new LinearLayout.LayoutParams(-1,0,1));list.setOnItemClickListener((p,v,n,id)->{if(n<rows.size())RepeaterProfiles.show(this,rows.get(n),db,this::reload);});root.addView(button("Online update / download map",()->new AlertDialog.Builder(this).setItems(new String[]{"Download RepeaterBook state (approved user token)","Download offline map from GitHub release"},(d,n)->{if(n==0)RepeaterDownloads.stateDialog(this,db,this::reload);else RepeaterDownloads.mapDialog(this);}).show()));setContentView(root);reload();}
 public void nearestAfterDownload(){nearest=true;reload();}
 private void radiusDialog(){EditText e=new EditText(this);e.setInputType(8194);e.setText(""+radius);new AlertDialog.Builder(this).setTitle("Search radius in km").setView(e).setNegativeButton("Cancel",null).setPositiveButton("Set",(d,w)->{try{radius=Double.parseDouble(e.getText().toString());if(radius<=0||radius>20000)throw new IllegalArgumentException();reload();}catch(Exception ex){message("Enter a radius from 1 to 20,000 km.");}}).show();}
 protected void onPosition(Location p){reload();}
 private void reload(){if(isFinishing()||worker.isShutdown())return;final Location p=position;final boolean sorted=nearest&&p!=null;status.setText("Loading local records…");worker.execute(()->{try{List<Repeater> next=sorted?db.nearest(p.getLatitude(),p.getLongitude(),radius):db.all();long count=db.count();runOnUiThread(()->{if(isFinishing())return;rows=next;ArrayList<String> names=new ArrayList<>();for(Repeater r:rows){String distance=p!=null&&r.located()?String.format(Locale.US," · %.1f km",Geo.distanceKm(p.getLatitude(),p.getLongitude(),r.latitude,r.longitude)):r.located()?"":" · no location";names.add(r.title()+"\n"+r.output+" MHz · "+r.mode+distance);}list.setAdapter(new ArrayAdapter<>(this,com.rumitx.app.R.layout.channel_card,names));status.setText(count+" stored · "+next.size()+" shown"+(sorted?" · nearest within "+radius+" km":" · alphabetical")+(nearest&&p==null?" · location unavailable":""));});}catch(Exception e){runOnUiThread(()->message("Database: "+e.getMessage()));}});}
 private void importOptions(){new AlertDialog.Builder(this).setItems(new String[]{"Choose CSV file","USB folder /sdcard/RumiTX/import"},(d,n)->{if(n==0){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,44);}else storage(this::usbFiles);}).show();}
 private void usbFiles(){File folder=new File(android.os.Environment.getExternalStorageDirectory(),"RumiTX/import");folder.mkdirs();File[] files=folder.listFiles(f->f.isFile()&&f.getName().toLowerCase(Locale.US).endsWith(".csv"));if(files==null||files.length==0){message("Copy your personal CSV export into /sdcard/RumiTX/import using USB, then Import again.");return;}Arrays.sort(files);String[] names=new String[files.length];for(int i=0;i<files.length;i++)names[i]=files[i].getName();new AlertDialog.Builder(this).setItems(names,(d,n)->importStream(()->new FileInputStream(files[n]))).show();}
 private interface Open {InputStream open()throws IOException;}
 private void importStream(Open opener){status.setText("Importing…");worker.execute(()->{try(InputStream in=opener.open()){RepeaterDatabase.ImportResult result=db.importCsv(new InputStreamReader(in,"UTF-8"));runOnUiThread(()->{message(result.toString());reload();});}catch(Exception e){runOnUiThread(()->message("Import failed; previous data retained. "+e.getMessage()));}});}
 protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(request==44&&result==RESULT_OK&&data!=null&&data.getData()!=null)importStream(()->getContentResolver().openInputStream(data.getData()));}
 protected void onDestroy(){worker.shutdownNow();new Thread(()->{try{worker.awaitTermination(10,TimeUnit.SECONDS);}catch(Exception ignored){}db.close();}).start();super.onDestroy();}
}
